blocks.body:
{
    "level": "A2–B2",
    "intro": "У цій темі ми зібрали <strong>найпоширеніші помилки<\/strong> при вживанні пасивного стану та практичні поради, як їх уникати. Вивчення помилок — найкращий спосіб їх не повторювати!",
    "rules": [
        {
            "label": "Be + V3",
            "color": "emerald",
            "text": "Не забувай <strong>дієслово be<\/strong> та <strong>V3 (Past Participle)<\/strong>:",
            "example": "The letter is written. ✅ (не: The letter written. ❌)"
        },
        {
            "label": "V3 ≠ V2",
            "color": "rose",
            "text": "Використовуй <strong>V3<\/strong>, не V2:",
            "example": "The window was broken. ✅ (не: was broke. ❌)"
        },
        {
            "label": "Без do\/does",
            "color": "blue",
            "text": "У питаннях <strong>не використовуй do\/does\/did<\/strong>:",
            "example": "Is the letter written? ✅ (не: Does the letter is written? ❌)"
        }
    ]
}

{
    "title": "1. Помилки з дієсловом BE",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Пропуск дієслова be.",
            "wrong": "The letter written yesterday.",
            "right": "✅ The letter was written yesterday."
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Неправильна форма be (is\/are).",
            "wrong": "The letters is sent every day.",
            "right": "✅ The letters are sent every day."
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Неправильна форма be (was\/were).",
            "wrong": "The windows was broken.",
            "right": "✅ The windows were broken."
        },
        {
            "label": "Помилка 4",
            "color": "rose",
            "title": "Пропуск been у Perfect.",
            "wrong": "The work has done.",
            "right": "✅ The work has been done."
        }
    ]
}

{
    "title": "2. Помилки з Past Participle (V3)",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Використання V1 (infinitive) замість V3.",
            "wrong": "English is speak here.",
            "right": "✅ English is spoken here."
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Використання V2 (past simple) замість V3.",
            "wrong": "The window was broke.",
            "right": "✅ The window was broken."
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Плутання неправильних дієслів.",
            "wrong": "The book was writed by him.",
            "right": "✅ The book was written by him."
        },
        {
            "label": "Помилка 4",
            "color": "rose",
            "title": "Використання -ing замість V3.",
            "wrong": "The letter is writing now.",
            "right": "✅ The letter is being written now."
        }
    ]
}

{
    "title": "3. Помилки в питаннях",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Використання do\/does\/did у питаннях.",
            "wrong": "Does the letter is written?",
            "right": "✅ Is the letter written?"
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Неправильний порядок слів.",
            "wrong": "The letter is written?",
            "right": "✅ Is the letter written?"
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Помилка у wh-питаннях.",
            "wrong": "Where the book was found?",
            "right": "✅ Where was the book found?"
        },
        {
            "label": "Помилка 4",
            "color": "rose",
            "title": "Неправильна коротка відповідь.",
            "wrong": "Was the work done? — Yes, it done.",
            "right": "✅ Was the work done? — Yes, it was."
        }
    ]
}

{
    "title": "4. Помилки в запереченнях",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Пропуск not або неправильне розташування.",
            "wrong": "The letter is not write.",
            "right": "✅ The letter is not written."
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Використання don't\/doesn't.",
            "wrong": "The work doesn't finished.",
            "right": "✅ The work isn't finished."
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Неправильна форма not.",
            "wrong": "The letter is no written.",
            "right": "✅ The letter is not written."
        },
        {
            "label": "Помилка 4",
            "color": "rose",
            "title": "Помилка в Perfect.",
            "wrong": "The work hasn't done.",
            "right": "✅ The work hasn't been done."
        }
    ]
}

{
    "title": "5. Помилки з by та with",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Використання with для виконавця.",
            "wrong": "The book was written with Shakespeare.",
            "right": "✅ The book was written by Shakespeare."
        },
        {
            "label": "Помилка 2",
            "color": "amber",
            "title": "Використання by для інструменту.",
            "wrong": "The letter was written by a pen.",
            "right": "✅ The letter was written with a pen."
        },
        {
            "label": "Помилка 3",
            "color": "sky",
            "title": "Зайвий by + agent.",
            "wrong": "My car was stolen by someone.",
            "right": "✅ My car was stolen."
        },
        {
            "label": "Помилка 4",
            "color": "rose",
            "title": "Неправильне розташування by.",
            "wrong": "By the team the report was prepared.",
            "right": "✅ The report was prepared by the team."
        }
    ]
}

{
    "title": "6. Правильні приклади вживання",
    "sections": [
        {
            "label": "Present Simple Passive",
            "color": "emerald",
            "description": "<strong>am\/is\/are + V3<\/strong>:",
            "examples": [
                {
                    "en": "English is spoken in many countries.",
                    "ua": "Англійською розмовляють у багатьох країнах."
                },
                {
                    "en": "The office is cleaned every day.",
                    "ua": "Офіс прибирається щодня."
                },
                {
                    "en": "Cars are made in Germany.",
                    "ua": "Машини виробляються в Німеччині."
                }
            ]
        },
        {
            "label": "Past Simple Passive",
            "color": "blue",
            "description": "<strong>was\/were + V3<\/strong>:",
            "examples": [
                {
                    "en": "The letter was sent yesterday.",
                    "ua": "Лист надіслали вчора."
                },
                {
                    "en": "The house was built in 1990.",
                    "ua": "Будинок був побудований у 1990 році."
                },
                {
                    "en": "The windows were broken during the storm.",
                    "ua": "Вікна розбилися під час бурі."
                }
            ]
        },
        {
            "label": "Present Perfect Passive",
            "color": "amber",
            "description": "<strong>has\/have been + V3<\/strong>:",
            "examples": [
                {
                    "en": "The work has been completed.",
                    "ua": "Робота завершена."
                },
                {
                    "en": "All tickets have been sold.",
                    "ua": "Усі квитки продані."
                },
                {
                    "en": "The report has been submitted.",
                    "ua": "Звіт подано."
                }
            ]
        },
        {
            "label": "Modal Passive",
            "color": "rose",
            "description": "<strong>modal + be + V3<\/strong>:",
            "examples": [
                {
                    "en": "The task must be done today.",
                    "ua": "Завдання має бути виконане сьогодні."
                },
                {
                    "en": "This problem can be solved.",
                    "ua": "Цю проблему можна вирішити."
                },
                {
                    "en": "The report should be checked carefully.",
                    "ua": "Звіт слід ретельно перевірити."
                }
            ]
        }
    ]
}

{
    "title": "7. Правильне перетворення Active → Passive",
    "intro": "Поетапне перетворення активних речень на пасивні:",
    "rows": [
        {
            "en": "Active: Tom writes letters.",
            "ua": "Том пише листи.",
            "note": "→ Passive: Letters are written by Tom."
        },
        {
            "en": "Active: She cleaned the room.",
            "ua": "Вона прибрала кімнату.",
            "note": "→ Passive: The room was cleaned."
        },
        {
            "en": "Active: They have finished the project.",
            "ua": "Вони завершили проєкт.",
            "note": "→ Passive: The project has been finished."
        },
        {
            "en": "Active: Someone must do this work.",
            "ua": "Хтось має зробити цю роботу.",
            "note": "→ Passive: This work must be done."
        }
    ],
    "warning": "📌 Object активного речення → Subject пасивного. Дієслово → be + V3."
}

{
    "title": "8. Чек-лист перевірки пасиву",
    "intro": "Перевір своє речення за цими пунктами:",
    "items": [
        {
            "label": "✓ 1",
            "title": "Чи є дієслово BE?",
            "subtitle": "am\/is\/are\/was\/were\/been\/being"
        },
        {
            "label": "✓ 2",
            "title": "Чи правильна форма BE за часом?",
            "subtitle": "Present: is\/are; Past: was\/were"
        },
        {
            "label": "✓ 3",
            "title": "Чи використано V3 (Past Participle)?",
            "subtitle": "written, broken, done, made"
        },
        {
            "label": "✓ 4",
            "title": "Чи правильна форма V3?",
            "subtitle": "broken (не broke), written (не writed)"
        },
        {
            "label": "✓ 5",
            "title": "Чи немає do\/does\/did у питаннях?",
            "subtitle": "Is it done? (не: Does it is done?)"
        },
        {
            "label": "✓ 6",
            "title": "Чи правильно by\/with?",
            "subtitle": "by + agent; with + instrument"
        }
    ]
}

{
    "title": "Passive Basics",
    "items": [
        {
            "label": "Formation Rules — Правила утворення пасиву",
            "current": false
        },
        {
            "label": "Passive with Modal Verbs — Пасив з модальними",
            "current": false
        },
        {
            "label": "Causative — have/get something done",
            "current": false
        },
        {
            "label": "Get-Passive — Розмовний пасив",
            "current": false
        },
        {
            "label": "Impersonal Passive — Безособовий пасив",
            "current": false
        },
        {
            "label": "Negatives & Questions in Passive — Питання й заперечення",
            "current": false
        },
        {
            "label": "Phrasal Verbs in Passive — Фразові дієслова",
            "current": false
        },
        {
            "label": "Restrictions — Обмеження пасиву",
            "current": false
        },
        {
            "label": "Two-object Verbs in Passive — give/send/offer",
            "current": false
        },
        {
            "label": "Common Mistakes in Passive — Типові помилки",
            "current": true
        },
        {
            "label": "Formality & Style in Passive — Формальність і стиль",
            "current": false
        }
    ]
}

{
    "level": "B2–C1",
    "intro": "У цій темі ти дізнаєшся, як <strong>стиль та формальність<\/strong> впливають на вибір між активом і пасивом, та коли використання пасиву є <strong>доречним<\/strong> або <strong>небажаним<\/strong>.",
    "rules": [
        {
            "label": "Формальний",
            "color": "emerald",
            "text": "Пасив надає тексту <strong>формальності та об'єктивності<\/strong>:",
            "example": "The experiment was conducted in 2023."
        },
        {
            "label": "Науковий",
            "color": "blue",
            "text": "У <strong>наукових текстах<\/strong> пасив — норма:",
            "example": "The data were analyzed using SPSS."
        },
        {
            "label": "Розмовний",
            "color": "amber",
            "text": "У <strong>розмовній мові<\/strong> актив звучить природніше:",
            "example": "We analyzed the data. (не: The data were analyzed by us)"
        }
    ]
}

{
    "title": "1. Де пасив типовий і доречний",
    "sections": [
        {
            "label": "Наукові тексти",
            "color": "emerald",
            "description": "У <strong>наукових статтях<\/strong> та дослідженнях:",
            "examples": [
                {
                    "en": "The experiment was conducted under controlled conditions.",
                    "ua": "Експеримент проводився в контрольованих умовах."
                },
                {
                    "en": "The samples were collected from five locations.",
                    "ua": "Зразки були зібрані з п'яти місць."
                },
                {
                    "en": "It was observed that temperature affects the results.",
                    "ua": "Було виявлено, що температура впливає на результати."
                }
            ]
        },
        {
            "label": "Офіційні документи",
            "color": "blue",
            "description": "У <strong>законах, контрактах, інструкціях<\/strong>:",
            "examples": [
                {
                    "en": "Smoking is prohibited in this area.",
                    "ua": "Куріння заборонено в цій зоні."
                },
                {
                    "en": "Applications must be submitted by Friday.",
                    "ua": "Заявки мають бути подані до п'ятниці."
                },
                {
                    "en": "This contract is governed by UK law.",
                    "ua": "Цей контракт регулюється законодавством Великобританії."
                }
            ]
        },
        {
            "label": "Новини та медіа",
            "color": "amber",
            "description": "У <strong>новинних повідомленнях<\/strong>:",
            "examples": [
                {
                    "en": "The suspect was arrested yesterday.",
                    "ua": "Підозрюваного заарештували вчора."
                },
                {
                    "en": "The new law has been approved.",
                    "ua": "Новий закон схвалено."
                },
                {
                    "en": "Several people were injured in the accident.",
                    "ua": "Кілька людей постраждали в аварії."
                }
            ]
        },
        {
            "label": "Технічні інструкції",
            "color": "rose",
            "description": "У <strong>технічній документації<\/strong>:",
            "examples": [
                {
                    "en": "The device should be charged for 2 hours.",
                    "ua": "Пристрій слід заряджати 2 години."
                },
                {
                    "en": "Cookies are used to improve user experience.",
                    "ua": "Cookies використовуються для покращення користувацького досвіду."
                },
                {
                    "en": "Updates are installed automatically.",
                    "ua": "Оновлення встановлюються автоматично."
                }
            ]
        }
    ]
}

{
    "title": "2. Формальний vs Неформальний стиль",
    "intro": "Порівняння одного повідомлення у різних стилях:",
    "rows": [
        {
            "en": "Formal: The report was submitted on time.",
            "ua": "Звіт було подано вчасно.",
            "note": "Офіційний документ, email."
        },
        {
            "en": "Informal: I submitted the report on time.",
            "ua": "Я подав звіт вчасно.",
            "note": "Розмова з колегою."
        },
        {
            "en": "Formal: Mistakes were made.",
            "ua": "Були допущені помилки.",
            "note": "Офіційна заява (без вказівки винуватця)."
        },
        {
            "en": "Informal: We made mistakes.",
            "ua": "Ми допустили помилки.",
            "note": "Визнання відповідальності."
        }
    ],
    "warning": "📌 Пасив може використовуватися для уникнення відповідальності або звинувачень!"
}

{
    "title": "3. Коли краще уникати пасиву",
    "sections": [
        {
            "label": "Розмовна мова",
            "color": "rose",
            "description": "У <strong>повсякденному спілкуванні<\/strong> пасив звучить неприродно:",
            "examples": [
                {
                    "en": "Unnatural: The ball was kicked by John.",
                    "ua": "Неприродно: М'яч був вдарений Джоном."
                },
                {
                    "en": "Natural: John kicked the ball.",
                    "ua": "Природно: Джон вдарив м'яч."
                }
            ]
        },
        {
            "label": "Коли важливий виконавець",
            "color": "amber",
            "description": "Якщо <strong>важливо, хто виконав дію<\/strong>:",
            "examples": [
                {
                    "en": "Awkward: The book was written by Shakespeare.",
                    "ua": "Зайвий пасив для відомого автора."
                },
                {
                    "en": "Better: Shakespeare wrote the book.",
                    "ua": "Краще: Шекспір написав книгу."
                }
            ]
        },
        {
            "label": "Надмірний пасив",
            "color": "blue",
            "description": "Занадто багато пасиву <strong>втомлює читача<\/strong>:",
            "examples": [
                {
                    "en": "Too much passive: The report was written, was reviewed, and was submitted.",
                    "ua": "Перевантажено пасивом."
                },
                {
                    "en": "Better: We wrote, reviewed, and submitted the report.",
                    "ua": "Краще: Ми написали, перевірили і подали звіт."
                }
            ]
        }
    ]
}

{
    "title": "4. Be-пасив vs Get-пасив за формальністю",
    "intro": "Вибір між <strong>be<\/strong> та <strong>get<\/strong> залежить від стилю:",
    "items": [
        {
            "label": "be + V3",
            "title": "Формальний, нейтральний",
            "subtitle": "The document was signed. (офіційно)"
        },
        {
            "label": "get + V3",
            "title": "Неформальний, розмовний",
            "subtitle": "The document got signed. (розмовно)"
        },
        {
            "label": "Наукові тексти",
            "title": "Тільки be-пасив",
            "subtitle": "The data were analyzed. ✅"
        },
        {
            "label": "Щоденне мовлення",
            "title": "Get-пасив допустимий",
            "subtitle": "He got promoted! (позитивна новина)"
        }
    ]
}

{
    "title": "5. Стилістичні ефекти пасиву",
    "sections": [
        {
            "label": "Об'єктивність",
            "color": "emerald",
            "description": "Пасив створює враження <strong>об'єктивності та неупередженості<\/strong>:",
            "examples": [
                {
                    "en": "It is believed that climate change is accelerating.",
                    "ua": "Вважається, що зміна клімату прискорюється."
                },
                {
                    "en": "The results were verified independently.",
                    "ua": "Результати перевірені незалежно."
                }
            ]
        },
        {
            "label": "Знеособлення",
            "color": "blue",
            "description": "Пасив <strong>приховує виконавця<\/strong> (іноді навмисно):",
            "examples": [
                {
                    "en": "Mistakes were made.",
                    "ua": "Були допущені помилки. (хто — невідомо)"
                },
                {
                    "en": "It has been decided to close the factory.",
                    "ua": "Вирішено закрити завод. (хто вирішив?)"
                }
            ]
        },
        {
            "label": "Фокус на дії\/об'єкті",
            "color": "amber",
            "description": "Пасив <strong>підкреслює дію або результат<\/strong>:",
            "examples": [
                {
                    "en": "The Mona Lisa was painted in the early 16th century.",
                    "ua": "Мона Ліза написана на початку 16 століття."
                },
                {
                    "en": "The building was destroyed in the fire.",
                    "ua": "Будівля знищена пожежею."
                }
            ]
        }
    ]
}

{
    "title": "6. Академічний стиль: рекомендації",
    "intro": "Сучасні рекомендації щодо пасиву в академічних текстах:",
    "rows": [
        {
            "en": "Traditional: The results were analyzed.",
            "ua": "Традиційно: пасив у методології.",
            "note": "Все ще широко використовується."
        },
        {
            "en": "Modern: We analyzed the results.",
            "ua": "Сучасно: актив з \"we\".",
            "note": "Рекомендовано багатьма журналами."
        },
        {
            "en": "Mixed: The samples were collected. We analyzed them.",
            "ua": "Змішаний стиль.",
            "note": "Баланс об'єктивності та ясності."
        }
    ],
    "warning": "📌 Перевіряй вимоги конкретного журналу або установи!"
}

{
    "title": "7. Типові помилки",
    "items": [
        {
            "label": "Помилка 1",
            "color": "rose",
            "title": "Get-пасив у формальному тексті.",
            "wrong": "The experiment got conducted.",
            "right": "✅ The experiment was conducted."
        },
        {
            "label": "Помилка 2",
            "color": "amber",
